def table(rows,widths=None,small=False):
    st='TinyFR' if small else 'SmallFR'
    th=ParagraphStyle(name='th',parent=styles[st],textColor=colors.white,fontName='DejaVu-Bold')
    data=[[Paragraph(str(c),th if ri==0 else styles[st]) for c in r] for ri,r in enumerate(rows)]
    t=Table(data,colWidths=widths or [CW/len(rows[0])]*len(rows[0]),repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),navy),('TEXTCOLOR',(0,0),(-1,0),colors.white),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,pale]),('LINEBELOW',(0,0),(-1,0),.7,navy),('LINEBELOW',(0,-1),(-1,-1),.5,colors.HexColor('#c6d3dd'))]))
    # Paragraph foreground is explicit, so set header styles individually.

    return t

