def image_fit(path,maxw=CW,maxh=290):
    from PIL import Image as PILImage
    with PILImage.open(path) as im:w,hh=im.size
    scale=min(maxw/w,maxh/hh)
    return Image(str(path),width=w*scale,height=hh*scale,hAlign='CENTER')
class Architecture(Flowable):
    def __init__(self):Flowable.__init__(self);self.width=CW;self.height=176
    def draw(self):
        c=self.canv
        boxes=[(0,116,145,48,'Acquisition','ADC/DMA → acq'),(181,116,145,48,'Événements','boutons + compteurs → evq'),(362,116,145,48,'Commande','fsm en C'),(181,20,145,48,'Communication','telem → LPUART1'),(362,20,145,48,'Pilotes conservés','GPIO, moteur, buzzer, ISR')]
        for x,y,w,hh,a,b in boxes:
            c.setFillColor(pale);c.setStrokeColor(blue);c.roundRect(x,y,w,hh,5,fill=1,stroke=1)
            c.setFillColor(navy);c.setFont('DejaVu-Bold',9);c.drawCentredString(x+w/2,y+29,a)
            c.setFont('DejaVu',7.5);c.drawCentredString(x+w/2,y+12,b)
        c.setStrokeColor(blue);c.setFillColor(blue)
        def arrow(x1,y1,x2,y2):
            c.line(x1,y1,x2,y2);ang=math.atan2(y2-y1,x2-x1);q=c.beginPath();q.moveTo(x2,y2);q.lineTo(x2-6*math.cos(ang-.5),y2-6*math.sin(ang-.5));q.lineTo(x2-6*math.cos(ang+.5),y2-6*math.sin(ang+.5));q.close();c.drawPath(q,fill=1,stroke=0)
        arrow(145,140,181,140);arrow(326,140,362,140);arrow(434,116,434,68);arrow(395,116,285,68)
        c.setFont('DejaVu',7.5);c.drawString(4,84,'main.c : initialisation, production, consommation et cadence 1 ms')
        c.drawString(4,7,'Les registres nouveaux restent dans adc_dma.c et telem.c ; evq/acq sont testables sur hôte.')

def build_report():
    story=[]
    def add(*x):story.extend(x)
    def page(title):add(PageBreak(),p(title,'H1FR'))
    m=json.loads((E/'mesures_compilation.json').read_text())
    add(p('Université d’Ottawa · Architecture d’ordinateurs II','SmallFR'),Spacer(1,13),p('Laboratoire 3<br/>Acquisition, événements<br/>et télémétrie','TitleFR'))
    add(p('<b>Eren Arikan</b> · 300357356<br/><b>Antony Zuze</b> · 300221295<br/>Section A02 · Automne 2026'),p('Rapport de réalisation et d’essais<br/>Énoncé v1.3 du 1<super>er</super> novembre 2026','SmallFR'),Spacer(1,10))
    add(h('1. Objectif et portée de la validation'),p('Le laboratoire remplace la boucle et la machine à états assembleur par une application C, tout en conservant les pilotes des laboratoires 1 et 2. Le potentiomètre fournit la consigne ; un ADC à deux voies et un DMA circulaire acquièrent la consigne et la température. Une file d’événements relie acquisition, commande et télémétrie. Une routine Thumb convertit les fronts de l’encodeur en vitesse Q16.16.'))
    add(table([['Élément','Résultat obtenu'],['Projet STM32CubeIDE','Construction Debug : 0 erreur, 0 avertissement. Firmware lié à -O0 et -O2.'],['File et calculs','12/12 essais de file sous Linux et QEMU ; 5/5 cas de vitesse assembleur, également vérifiés sur STM32.'],['Commande et émission','Tests hôte des transitions, rampe, urgence injectée, filtrage, trames et saturation réussis.'],['Comparaison assembleur/C','8/8 cas PWM à -O0 et -O2 sur STM32, zéro écart ASM/C ; tests QEMU conservés.'],['Validation matérielle','Connexion rétablie à 3,24 V. STM32 programmé ; ADC, file, UART et cycles DWT mesurés. Deux sens et E-Stop testés ; calibration thermique et latence restent ouvertes.']], [142,CW-142]))
    add(Spacer(1,10),p('<b>Lecture des preuves.</b> « Réussi sous Linux » désigne un essai du code sur l’hôte. « Réussi sous QEMU » désigne une exécution du code ARM sur un processeur émulé. Les captures sont des vues des journaux enregistrés ; la photographie de plateforme est une prise de vue réelle. Les données de télémétrie synthétiques ne sont pas présentées comme une acquisition sur carte.','SmallFR'))
    add(p('Hypothèses retenues : MSI/HCLK/PCLK1 = 4 MHz ; fenêtre encodeur = 250 ms ; 748 fronts par tour ; ADC 12 bits et VREF = 3 300 mV ; deux voies ; 16 échantillons pour le potentiomètre et 64 pour la température en version 2. Le point thermique 1 831 mV à 25,0 °C est une référence initiale du complément, à étalonner sur la plateforme.','SmallFR'))

    page('2. Conception et interfaces · L3-B')
    add(p('Le problème consiste à maintenir la réactivité des commandes et de l’arrêt d’urgence, sans attente de transmission série, avec une mémoire fixe et des modules testables sans matériel. Une tâche lente ou une file pleine ne doit pas empêcher la mise en sécurité. Les accès aux registres des anciens pilotes restent exclusivement en assembleur.'))
    add(table([['Critère','Scrutation directe','File d’événements retenue'],['Couplage','Chaque lecture peut déclencher directement les sorties.','Producteurs et consommateur communiquent par type, valeur et date.'],['Testabilité','Le contrôle dépend souvent des broches et du temps réel.','evq et acq fonctionnent en mémoire ; fsm accepte des événements injectés.'],['Mémoire/temps','Peu de stockage ; ordre implicite de traitement.','32 entrées fixes, opérations push/pop en temps constant.'],['Surcharge','Un événement peut être écrasé implicitement.','Refus explicite, compteur de débordements et contenu FIFO conservé.']], [87,197,CW-284]))
    add(Spacer(1,12),Architecture(),h('Contrats des modules'))
    add(p('<b>evq</b> stocke 32 structures de 12 octets, soit 384 octets de données. Tous ses appels proviennent de main ; les ISR ne manipulent pas la file. <b>acq</b> reçoit une source volatile, un pas, un nombre d’échantillons et une calibration. Son en-tête ne révèle pas ses champs. <b>adc_dma</b> connaît les registres et publie la position de la prochaine paire complète. <b>fsm</b> consomme un événement à la fois et regroupe les appels aux sorties dans fsm_sorties. <b>telem</b> reçoit un état exposé, construit une ligne CSV et la met en attente sans attendre la liaison.'))
    add(p('Le choix de la file rend l’ordre des événements visible et permet les essais de saturation. Son coût est borné : 384 octets pour les entrées, plus cinq compteurs de 32 bits. Elle ne remplace pas l’arrêt matériel : l’ISR E-Stop coupe déjà le moteur. Une voie prioritaire transmet également EV_ESTOP à la machine à états lorsque la file est pleine.'))

    page('3. Migration en C et commande')
    add(h('Conservation des pilotes et AAPCS'),p('Les fichiers gpio.s, buttons.s, estop.s, motor.s, encoder.s, systick.s et buzzer.s ont été repris du projet Lab 2 local retrouvé. La comparaison initiale confirmait leur conservation. Le test matériel a ensuite révélé un défaut hérité dans encoder_read : MOVS r2,#0 détruisait les drapeaux de SUBS avant BEQ/BPL. Un correctif minimal MOV.W conserve les drapeaux ; interface conservée. La constante ENC_SENS_INVERSE est ensuite réglée à 1 après observation des deux sens inversés. Ces exceptions sont documentées dans correctif_encodeur.md et doit être présentée à l’assistant. main.s et fsm.s sont remplacés par main.c et fsm.c. Le démarrage, le script de liens et les fichiers de support générés sont conservés. Les empreintes sont consignées dans preservation_lab2.txt.'))
    add(p('Les prototypes de lab1.h et lab2.h conservent les paramètres 32 bits et les pointeurs attendus. estop_flag, enc_count, sens_mesure, ticks_ms, tick_1ms et buzzer_continu restent volatile. Le programme appelle d’abord les initialisations GPIO, buzzer, moteur, encodeur, E-Stop et SysTick, puis la couche C. fsm_init impose l’arrêt et la DEL rouge ; telem_entete prépare la ligne H.'))
    add(table([['État / événement','Transition et sorties'],['ARRÊT + User','Départ en avant, puis en arrière au départ suivant. PWM repart de 0.'],['MARCHE + User','Passage par ARRÊT ; PWM, AI1/AI2 et STB coupés avant toute nouvelle direction.'],['MARCHE + consigne','Consigne limitée à 0..100 %. Rampe de 1 point toutes les 10 ms.'],['Tout état + E-Stop','ARRÊT_URGENCE, PWM/STB coupés, rouge clignotante, son continu.'],['Urgence + Touch En','Acquittement seulement si E-Stop est relâché ; retour en ARRÊT, jamais en marche.'],['Touch En hors urgence','Bascule de touch_enabled et un bip, sans modification de la consigne.']], [145,CW-145]))
    add(h('Priorité de l’urgence et limites de concurrence'),p('Le drapeau E-Stop reste verrouillé jusqu’à l’acquittement. main notifie chaque verrouillage une fois et traite l’urgence avant les appuis ordinaires. Si push refuse l’événement, le débordement est compté et l’urgence est traitée directement. fsm_sorties vérifie aussi le drapeau avant et après les appels de sortie afin de recouper les sorties si l’ISR a préempté une écriture. Un essai hôte injecte précisément cette situation pendant motor_set_pwm.'))
    add(p('Les lectures alignées de mots de 32 bits sont atomiques individuellement sur cette cible ; volatile impose les accès, sans rendre une séquence lecture-modification-écriture atomique. Le bit tick_1ms peut fusionner plusieurs ticks pendant une opération de diagnostic. La cadence nominale et les trames pendant E-Stop ont été mesurées. La latence électrique inférieure à 1 ms reste à mesurer indépendamment de la télémétrie.','SmallFR'))

    page('4. Acquisition ADC/DMA et télémétrie')
    add(h('Configuration de l’acquisition'),p('PC0 et PC1 sont placées en mode analogique sans résistances de rappel. ADC1 utilise HCLK/1 ; le programme quitte DEEPPWD, active le régulateur, attend via SysTick, réalise l’étalonnage simple entrée et attend ADRDY. Les conversions continues alternent IN1 puis IN2, avec 640,5 cycles d’échantillonnage et 12,5 cycles de conversion. DMA1 canal 1, requête DMAMUX 5, transfère des demi-mots dans le tampon circulaire.'))
    add(table([['Paramètre','Valeur / calcul'],['ADC CFGR, SMPR1, SQR1','0x3003 ; 0x1F8 ; 0x2041 (champs programmés à l’initialisation).'],['DMA CCR et CNDTR','0x5A1 ; 128 demi-mots = 64 paires, soit 256 octets.'],['Débit par voie','4 000 000 / [2 × (640,5 + 12,5)] = 3 062,79 échantillons/s.'],['Durée de l’historique','16 échantillons : 5,224 ms ; 64 : 20,896 ms.'],['Vérification prévue','Différence de adc_dma_tours sur 1 s × 64 ; vérifier aussi CNDTR et le tampon.']], [145,CW-145]))
    add(p('Le compteur de tours observe le drapeau TCIF1 à chaque tick. Il n’est exact que si la boucle observe chaque fin de tour : plusieurs tours entre deux lectures ne sont pas récupérables à partir d’un seul bit. Sur STM32, 96 tours en environ 2 s donnent 3 072 échantillons/s/voie (+0,30 %), avec incertitude de phase du compteur. Le curseur exclut une paire dont IN2 n’est pas encore transférée ; l’acquisition attend un premier tour avant de publier la consigne.'))
    add(h('LPUART1 et format'),p('PWR_CR2.IOSV alimente PG7/PG8, configurées en AF8. LPUART1 utilise PCLK1 à 4 MHz, 115 200 bauds, 8N1, sans contrôle de flux. BRR = round(256 × 4 000 000 / 115 200) = 8 889 = 0x22B9. La FIFO matérielle est activée. La file logicielle contient 512 octets ; une ligne est réservée entièrement avant copie. Une file pleine rejette donc une ligne complète au lieu de produire une trame tronquée.'))
    add(p('H,ticks_ms,etat,sens,consigne_pct,pwm_pct,temp_c_x10,<br/>vitesse_rpm_x100,nb_evenements,evq_debordements','CodeFR'))
    add(p('Chaque ligne T porte les mêmes neuf champs, puis CRLF. À 5 Hz, une ligne d’environ 60 caractères représente 300 octets/s, soit environ 2,6 % de la liaison 8N1. telem_step écrit au plus huit caractères prêts et revient immédiatement ; elle est appelée aussi entre les ticks. Le formateur utilise uniquement des entiers. La conversion de vitesse d’affichage emploie un produit 64 bits pour éviter le débordement avant le décalage.'))
    add(p('Le vérificateur Python fourni a été corrigé pour faire échouer réellement une cadence incorrecte, un en-tête absent, moins de trois trames ou une terminaison incorrecte. Il gère aussi le débordement 32 bits de ticks_ms. Les 150 trames de test respectent le format et les dates synthétiques à 200 ms ; elles ne valident pas le débit réel du port série.','SmallFR'))

    page('5. Objet d’acquisition et évolution · L3-C')
    add(p('acq_t est un type incomplet dans acq.h. Ses champs se trouvent uniquement dans acq.c ; acq_instance fournit deux objets statiques, sans allocation dynamique. Chaque instance possède sa source, son pas, sa longueur de moyenne, son gain, son décalage et, en V2, son état de filtrage et son curseur. Les appels de lecture restent acq_brut, acq_mv et acq_valeur.'))
    add(table([['','Version 1','Version 2'],['Moyenne','16 échantillons par voie sur le tampon complet.','Potentiomètre : 16 derniers ; température : 64 derniers, avec curseur circulaire.'],['Conversion','Relation linéaire indépendante par instance.','Même relation ; zone morte et hystérésis configurables.'],['Changement appelant','Initialisation de deux instances.','Seule l’initialisation et la capacité du tampon changent ; lectures/fsm identiques.'],['État privé ARM','24 octets par instance.','56 octets par instance, soit 112 pour les deux.'],['Trace de version','Tag local acq-v1 ; baseline explicite.','Tag local acq-v2 ; tests et comparaison fournis.']], [95,190,CW-285]))
    add(p('La moyenne est arrondie à l’entier le plus proche. La tension est calculée par (brut × 3 300 + 2 047) / 4 095. Le filtre applique une zone morte de 3 % aux deux extrémités avant l’arrondi final ; la sortie n’est mise à jour que lorsque l’écart dépasse deux points. Les cas bruts 0, 122, 123, 3 972, 3 973 et 4 095 donnent respectivement 0, 0, 3, 97, 100 et 100 % lorsque le filtre est réinitialisé.'))
    add(p('Les essais vérifient le passage d’une moyenne de 16 à 64, l’enroulement, le maintien à 50 % pour une entrée de 52 %, puis le passage à 53 %. Réinitialiser le gain du potentiomètre de 100/3 300 à 50/3 300 modifie sa sortie de 50 à 25 sans changer celle de la température. L’annexe impérative compilable emploie des variables globales dédiées ; ajouter une voie y oblige à multiplier état et fonctions.'))
    add(h('Température et conditionnement externe'),p('La calibration initiale est t10 ≈ 250 - (mv - 1 831) × 10 000 / 10 900. Elle doit être ajustée avec un thermomètre. Un pas ADC vaut 0,806 mV, soit environ 0,0739 °C avec la pente de -10,9 mV/°C. Sur 15..40 °C, le signal varie d’environ 272,5 mV. Un gain externe de 4 donnerait 1,09 V de variation et 0,0185 °C par pas, mais exige un décalage : amplifier directement 1,831 V dépasserait 3,3 V.'))
    add(p('Exemple calculé : Vout = 1,65 V - 4 × 10,9 mV/°C × (T - 25 °C), soit 2,086 V à 15 °C et 0,996 V à 40 °C. Le gain n’améliore pas le bruit propre du capteur et ajoute celui du circuit. Une moyenne de 64 au lieu de 16 divise théoriquement l’écart-type par deux si le bruit est indépendant, avec une fenêtre quatre fois plus longue.','SmallFR'))
    add(p('<b>Limites :</b> capacité statique de deux instances, pas de polymorphisme, source valide et paramètres numériques bornés requis. Les lectures demi-mot sont indivisibles, mais un tour DMA entier n’est pas un instantané atomique. Le filtre peut donc réunir des valeurs prises à des instants voisins pendant la lecture.','SmallFR'))

    page('6. Vitesse en virgule fixe et AAPCS')
    add(p('Pour une fenêtre de 250 ms, la vitesse de sortie est fronts × 240 / 748 tr/min. Le format Q16.16 représente cette vitesse par un entier non signé divisé par 65 536. La constante idéale est 21 027,5935829 ; l’arrondi retenu est <b>k = 21 028</b>. L’erreur relative est +0,00193278 %, inférieure à 0,05 %. Pour zéro front, le résultat est exactement zéro.'))
    rows=[['Fronts','Référence tr/min','Q16.16 obtenu','Tr/min obtenu']]
    for n in (0,1,748,1870,65535):rows.append([str(n),f'{n*240/748:.6f}',str(n*21028),f'{n*21028/65536:.6f}'])
    add(table(rows,[67,145,145,CW-357]),Spacer(1,9),p('Les cinq résultats ont été obtenus sous QEMU à -O0/-O2 puis par appels GDB sur le STM32 réel à -O0 (arguments injectés). Le produit maximal demandé, 65 535 × 21 028 = 1 378 069 980, tient sur 32 bits. La limite exacte avant débordement est floor((2³² - 1) / 21 028) = 204 249 fronts. La routine n’effectue pas de saturation au-delà de ce contrat.'))
    add(p('movw r1, #21028<br/>mul r0, r0, r1<br/>bx lr','CodeFR'),p('Il s’agit d’une fonction feuille de 10 octets d’instructions : R0 reçoit le nombre de fronts et retourne le résultat ; seul R1 est utilisé comme temporaire. Aucun registre préservé R4-R11 n’est modifié et SP ne change pas.'))
    add(image_fit(E/'captures/02_gdb_vitesse.png',maxh=295),p('Capture P3 : R0 = 1 870 à l’entrée ; R0 = 39 322 360 au retour. SP = 0x30003F98 et SP &amp; 7 = 0. enc_count est le symbole réel du pilote conservé ; sa valeur 1 870 a été injectée par le banc. Vue intégrale dans les annexes et journal GDB brut fourni.','CaptionFR'))

    page('7. Comparaison assembleur / C · L3-A')
    add(p('La routine conservée choisie est motor_set_pwm. Elle sature un uint32_t à 100, calcule CCR1 = pct × 200 / 100, écrit TIM1_CCR1 et retourne la valeur écrite. Sa version C possède le même prototype. La production continue d’appeler la version assembleur ; la version C sert uniquement au banc.'))
    add(table([['Entrée pct','Retour ASM','Retour C','CCR1 ASM / C'],['0','0','0','0 / 0'],['1','2','2','2 / 2'],['25','50','50','50 / 50'],['50','100','100','100 / 100'],['75','150','150','150 / 150'],['99','198','198','198 / 198'],['100','200','200','200 / 200'],['4 294 967 295','200','200','200 / 200']], [130,105,105,CW-340]))
    add(p('Résultat matériel : zéro écart pour les huit cas à -O0 et -O2. Le banc commande b écrit le vrai CCR1 avec STB maintenu bas. Les tableaux en mémoire à -O0 et les retours série sont conservés. Ces essais ne prouvent pas la rotation du moteur. Les premiers résultats QEMU, avec TIM1 redirigé en RAM, restent identifiés séparément.','SmallFR'))
    add(table([['Symbole / mesure','-O0','-O2'],['motor_set_pwm (assembleur)','24 octets','24 octets'],['motor_set_pwm_c','64 octets','20 octets'],['fsm_etat','68 octets','56 octets'],['fsm_traiter','364 octets','372 octets'],['Cycles DWT ASM / C / fsm','32 / 50 / 44','23 / 19 / 22']], [CW-190,95,95]))
    add(p('Les tailles sont celles des symboles ELF : elles peuvent inclure un littéral interne, tandis qu’un pool externe au symbole n’y est pas compté. À -O2, le compilateur sait que pct ≤ 100 ; il remplace multiplication et division par un décalage d’un bit et supprime les variables locales sur la pile. À -O0, il conserve une trame et davantage d’accès mémoire. L’écriture volatile de CCR1 reste présente dans les deux cas.'))
    add(p('Le banc a été exécuté sur la carte : commande b en ARRÊT, STB maintenu bas, lecture de DWT_CYCCNT avant/après et soustraction d’une mesure vide. Il expose les cycles moyens ASM/C et ceux de fsm_etat. Les interruptions restent actives ; plusieurs répétitions sont nécessaires pour identifier leur effet. Aucune durée QEMU n’est convertie en cycles STM32. Le banc final -O2 redonne 23/19/22 cycles.','SmallFR'))

    page('8. Outils, encodages et optimisation · L3-D')
    add(p('Le projet a été compilé avec GNU Tools for STM32 14.3.1 pour Cortex-M33/Thumb, en gnu11, avec -Wall -Wextra. La construction en ligne de commande ajoute -Werror. Les listes -d -S de motor_set_pwm_c et de fonctions de fsm.c sont fournies pour -O0 et -O2. Les captures GDB montrent paramètres, retour, pile et variable volatile sous QEMU et sur STM32 réel (annexe H3).'))
    add(table([['Source C','Instruction Thumb -O2','Encodage / octets en mémoire'],['if (pct &gt; 100u)','cmp r0, #100','0x2864 / 64 28'],['pct * 200u / 100u','lsls r0, r0, #1','0x0040 / 40 00'],['TIM1-&gt;CCR1 = ccr','str r0, [r3, #52]','0x6358 / 58 63']], [165,150,CW-315]))
    add(p('Pour <b>0x6358</b>, le format STR immédiat 16 bits est <font name="Mono">01100 imm5 Rn Rt</font>. Ici imm5 = 13, Rn = 3 et Rt = 0. Le déplacement vaut 13 × 4 = 52 octets = 0x34, l’offset de CCR1. R3 porte la base TIM1 = 0x40012C00. L’instruction écrit donc R0 à 0x40012C34. Cette correspondance relie directement la ligne C, l’assembleur et le code machine.'))
    add(h('Effets observés sur fsm.c'),p('À -O2, fsm_etat lit toujours les quatre variables volatile puis copie leurs valeurs dans l’état exposé ; le compilateur peut regrouper des écritures non volatile, par exemple avec STRD, mais ne supprime pas les lectures requises. Il préserve R4 dans une fonction feuille. L’alignement AAPCS de huit octets s’applique aux interfaces ; une fonction feuille peut ajuster temporairement sa pile tout en rétablissant SP au retour.'))
    add(p('L’optimisation ne réduit pas systématiquement la taille : fsm_traiter passe ici de 364 à 372 octets. Elle peut aussi rendre la correspondance ligne/instruction moins directe et éliminer des variables visibles au débogueur. -O0 est retenu pour les captures de paramètres ; -O2 est fourni pour la comparaison et la version optimisée. DWT donne les valeurs ci-contre. La différence entre les mesures ASM aux deux optimisations reflète aussi le contexte du banc et le coût de mesure ; elle ne signifie pas que les instructions ASM ont changé.'))
    add(table([['Firmware complet','text','data','bss'],['-O0',*map(str,m['firmware']['O0'])],['-O2',*map(str,m['firmware']['O2'])]], [CW-225,75,75,75]))
    add(p('Les colonnes sont celles de arm-none-eabi-size. data s’ajoute au texte pour l’image de chargement ; data et bss occupent la RAM, avec les réservations du script de liens. Les pilotes assembleur inchangés, le démarrage et les bibliothèques liées font partie de ces totaux.','SmallFR'))
    add(p('Reproduction : bash build.sh O0 puis bash build.sh O2 ; tests/run_target.sh pour le banc Cortex-M33 ; tests/qemu/debugger.gdb pour les points d’arrêt. Les exécutables ELF, journaux et fichiers de désassemblage sont inclus.','CodeFR'))

    page('9. Tableau de vérification T1 à T10')
    add(p('Le verdict indique exactement ce qui a été observé. Un essai logiciel ne remplace pas un essai matériel. Les essais sur STM32 sont distingués des simulations et des manipulations physiques encore non validées.','SmallFR'))
    add(table([['Essai','Procédure / résultat observé','Preuve et verdict'],
    ['T1 Initialisation','STM32 programmé. ARRÊT, PWM=0, H reçu ; première trame à ticks=203. DEL et délai électrique non photographiés.','H1/H2, gdb_initial_O0.log.<br/>Partiel matériel.'],
    ['T2 C → ASM','Appels réels depuis C : R0, LR, pile ; SP &amp; 7 = 0. enc_count lu en mémoire.','H3, gdb_aapcs_O0.log.<br/>Réussi sur STM32.'],
    ['T3 Virgule fixe','Cinq arguments injectés sur STM32 ; résultats Q16.16 exacts, comme sous QEMU.','H4, gdb_vitesse_registres_O0.log.<br/>5/5 sur cible.'],
    ['T4 ADC/DMA','0 / 2053 / 4093 ; environ 3 072 échantillons/s/voie sur 2 s (+0,30 %). Tampon et registres lus.','H4/H6/H7, CSV ADC.<br/>Acquisition validée ; durée de comptage adaptée.'],
    ['T5 Consigne','PWM nul en ARRÊT. Deux sens 0..100 % enregistrés ; sens 1/2 correct après correction/calibration. Avant 21 % ~73 rpm ; arrière 36 % ~129 rpm.','essais_physiques.csv, H9.<br/>Réussi fonctionnellement sur la plateforme.'],
    ['T6 Température','Lecture ambiante ~25 °C ; chauffage par doigts : 25,3→29,4 °C. Calibration de départ conservée.','CSV réel.<br/>Réponse au chauffage validée ; thermomètre absent ; comparaison Int/Ext non validée.'],
    ['T7 File','Q,echecs=0 sur STM32. Saturation : huit refus sans arrêt du programme ; 12 cas sur Linux/QEMU.','H5 ; diagnostic_O0.csv.<br/>Cible/Linux réussis ; Windows non exécuté.'],
    ['T8 E-Stop','EV_ESTOP physique : flag 1, PB2=1, CCR1/STB=0. Coupure depuis 100 % (~374 rpm), trames intactes. Essai isolé : maintien jusqu’à EV_TOUCH, puis ARRÊT sans reprise.','H8 ; log déclenchement.<br/>Coupure et acquittement validés ; délai &lt; 1 ms non mesuré.'],
    ['T9 Télémétrie','O0 :149 trames/30 s, 4,98 Hz. Image finale O2 :150 trames/30 s, 5,00 Hz ; CRLF et neuf champs valides.','H2 ; serie_reelle_30s.csv.<br/>Réussi en régime nominal -O0/-O2.'],
    ['T10 Comparaison','Huit cas sans écart à -O0/-O2. Cycles ASM/C/fsm : 32/50/44 et 23/19/22. Tailles et encodages conservés.','H5/H6 ; logs et objdump.<br/>Mesures matérielles ponctuelles.']], [65,255,CW-320],small=True))
    add(Spacer(1,9),p('Les captures H1-H14 et journaux bruts complètent les premières preuves P1-P7. Les pauses au débogueur et les captures contenant des données antérieures ne sont pas utilisées comme preuve de cadence nominale. Le journal indique le défaut découvert, son correctif et les critères encore ouverts.','SmallFR'))

    page('10. Bilan, traçabilité et références')
    add(p('L’implémentation logicielle et le projet STM32CubeIDE sont réalisés. Les essais reproductibles confirment le fonctionnement de la file, des objets d’acquisition, du contrôle simulé, du formateur de télémétrie et des calculs assembleur. Ils établissent également les interfaces AAPCS et la comparaison de code aux deux optimisations. Les mesures matérielles ajoutent ADC/DMA, télémétrie réelle, file sur cible, AAPCS et cycles DWT. Les deux sens et la coupure E-Stop sont observés. La calibration thermique et la latence inférieure à 1 ms ne sont pas certifiées par ces seuls résultats.','SmallFR'))
