def build_proofs():
    items=[('P1','00_compilation','Construction STM32CubeIDE, projet complet. Aucun chargement sur carte.'),('P2','01_tests_linux','Tests hôte : file, acquisition, commande avec sorties substituées et télémétrie.'),('P3','02_gdb_vitesse','GDB sur Cortex-M33 QEMU : R0, SP, pile, variable partagée et retour Q16.16.'),('P4','03_gdb_pwm','GDB : appel PWM assembleur ; TIM1 explicitement redirigé en RAM.'),('P5','04_gdb_resultats','Valeurs réellement obtenues sous QEMU ; les tableaux PWM portent sur la mémoire simulée.'),('P6','05_telemetrie','Trames synthétiques produites par le formateur C. Aucune lecture d’un port série physique.'),('P7','06_desassemblage','Désassemblage du firmware STM32 à -O2, avec correspondance source C.')]
    st=[]
    for i,(num,name,caption) in enumerate(items):
        if i:st.append(PageBreak())
        st += [p(f'{num} · Preuve logicielle','H1FR'),p(caption),image_fit(E/f'captures/{name}.png',maxh=620),Spacer(1,10),p('La capture montre une vue HTML du journal brut, sans substitution de valeurs. Le fichier PNG haute résolution et les journaux complets sont inclus dans preuves/. Cette annexe conserve les preuves de la phase logicielle initiale. Les essais ultérieurs sur STM32 et les cycles DWT figurent dans Preuves_Materielles_CEG3536_Lab3.pdf.','SmallFR')]
    target=OUT/'Annexes_Preuves_CEG3536_Lab3.pdf'
    SimpleDocTemplate(str(target),pagesize=A4,rightMargin=44,leftMargin=44,topMargin=42,bottomMargin=51,title='CEG3536 Lab3 - Annexes de preuves').build(st,onFirstPage=lambda c,d:footer(c,d,'Annexe'),onLaterPages=lambda c,d:footer(c,d,'Annexe'))
    return target

def build_fiches():
    st=[p('Fiche périphérique · ADC1 / DMA1','H1FR'),p('CEG3536 Lab 3 · Arikan - Zuze · Configuration réalisée, acquisitions matérielles relevées.','SmallFR'),h('Rôle et connexions'),p('Acquérir en continu le potentiomètre Speed sur PC0/ADC1_IN1 et le capteur de température sur PC1/ADC1_IN2. Horloge HCLK = 4 MHz. ADC 12 bits ; voies simples ; conversion continue ; échantillonnage maximal. S2 en position interne pour l’étalonnage initial.'),table([['Bloc / champ','Configuration'],['GPIOC','MODER0/1 = analogique ; PUPDR0/1 = aucun rappel.'],['Alimentation ADC','DEEPPWD = 0 ; ADVREGEN = 1 ; attente ; ADCAL ; ADEN ; ADRDY.'],['ADC12_COMMON CCR','CKMODE = 01 (HCLK/1).'],['ADC1 CFGR','CONT | DMAEN | DMACFG | OVRMOD ; résolution 12 bits ; valeur 0x3003.'],['ADC1 SMPR1 / SQR1','SMP1 = SMP2 = 111 ; L = 1 ; SQ1 = 1 ; SQ2 = 2. Valeurs 0x1F8 / 0x2041.'],['DMA1 canal 1','CPAR = &amp;ADC1-&gt;DR ; CM0AR = tampon ; CNDTR = 128.'],['DMA CCR','MINC | PSIZE_0 | MSIZE_0 | CIRC | EN = 0x5A1. DIR = 0.'],['DMAMUX1 canal 0','Requête ADC1 = 5.'],['Tampon','128 uint16_t volatile ; 64 paires ; 256 octets.']], [145,CW-145]),h('Calculs et cas d’essai'),p('Débit attendu : 3 062,79 échantillons/s par voie. Un tour de 64 paires dure 20,896 ms ; environ 47,86 tours/s. À 0 %, 50 % et 100 %, vérifier des valeurs proches de 0, 2 048 et 4 095, puis relever les tensions. Le nombre de tours doit être observé sans interrompre la boucle plus longtemps qu’un tour.'),p('Pour la température, relever la tension et le thermomètre au repos, mettre à jour TEMP_MV_REF et TEMP_C10_REF, puis tenir le capteur 30 s. Comparer ensuite le conditionnement interne à un pont OUT-IN sur J5, câblé hors tension.'),h('Résultats et traces disponibles'),p('Moyennes, enroulement, filtres et indépendance d’instances : essais hôte réussis. Configuration : compilation ARM réussie. Sur STM32 : brut 0/2053/4093 ; DMA estimé à 3 072 échantillons/s/voie. Chauffage par doigts : 25,3→29,4 °C. Thermomètre absent. Essais Ext incohérents (~1,0-1,2 V) ; retour Int plausible (~1,82 V). Connexion J5 à faire vérifier. Traces : tests_linux.log, acq_v1.log, adc_dma.c, acq.c. Source de configuration : énoncé v1.3 §4.8 et en-têtes CMSIS fournis.','SmallFR'),PageBreak(),p('Fiche périphérique · LPUART1 / PWR','H1FR'),p('CEG3536 Lab 3 · Arikan - Zuze · Émission non bloquante à 115 200 bauds.','SmallFR'),h('Rôle et connexions'),p('Émettre la télémétrie CSV vers le port COM virtuel du ST-LINK : PG7 TX et PG8 RX, AF8, 8 bits, sans parité, un bit d’arrêt, sans contrôle de flux. Le domaine VDDIO2 du port G est activé avant les broches.'),table([['Bloc / champ','Configuration'],['RCC / PWR','PWREN puis PWR_CR2.IOSV = 1 ; GPIOGEN ; LPUART1EN.'],['RCC CCIPR1','LPUART1SEL = 00, PCLK1 = 4 MHz.'],['GPIOG','MODER7/8 = AF ; AFRL7 = 8 ; AFRH8 = 8 ; rappel haut sur RX.'],['LPUART1 BRR','round(256 × 4 000 000 / 115 200) = 8 889 = 0x22B9.'],['LPUART1 CR1','FIFOEN | TE | RE | UE ; CR2 = CR3 = 0.'],['Émission','Tester TXE_TXFNF ; écrire TDR ; au plus huit octets par appel.'],['Réception','Tester RXNE_RXFNE ; lire RDR ; effacer ORE par ORECF.'],['File logicielle','512 caractères ; réservation de la ligne complète ; pertes comptées.']], [145,CW-145]),h('Calculs et cas d’essai'),p('L’horloge satisfait 4 MHz ≥ 3 × 115 200. Une trame de 60 caractères à 5 Hz utilise environ 300 octets/s, soit 2,6 % des 11 520 octets/s théoriques en 8N1. Vérifier la ligne H au reset, l’ordre des neuf champs, CRLF, 150 trames environ en 30 s, et l’intégrité pendant E-Stop.'),p('Sur carte : ouvrir le port avec hote/telemetrie.py, redémarrer la carte après ouverture pour capturer H, enregistrer 30 s et conserver le journal. Utiliser t pour saturer la file d’événements ; a affiche notamment les pertes de transmission. Les commandes q et b sont des diagnostics en ARRÊT.'),h('Résultats et traces disponibles'),p('BRR, formatage entier, INT32_MIN, rejet atomique, enroulement et absence d’attente quand TX n’est pas prêt : tests hôte réussis. 150 trames synthétiques vérifiées à 5 Hz dans leurs horodatages. Sur ST-LINK réel : image finale -O2,150 trames en 30 s,5,00Hz. Trames intactes lors du passage 100 % vers E-Stop. La latence électrique &lt; 1 ms reste non mesurée. Traces : tests_linux.log, telemetrie_synthetique.csv, capture P6.','SmallFR')]
    target=OUT/'Fiches_Peripheriques_CEG3536_Lab3.pdf'
    SimpleDocTemplate(str(target),pagesize=A4,rightMargin=44,leftMargin=44,topMargin=42,bottomMargin=51,title='CEG3536 Lab3 - Fiches peripheriques').build(st,onFirstPage=lambda c,d:footer(c,d,'Fiche'),onLaterPages=lambda c,d:footer(c,d,'Fiche'))
    return target
if __name__=='__main__':
    (P/'rapport').mkdir(exist_ok=True)
    for target in (build_report(),build_proofs(),build_fiches()):
        shutil.copy2(target,P/'rapport'/target.name)
        print(target)
